INSERT INTO "Tbl_PlantillaCorreo" ("id", "Plantilla", "EsHtml", "Asunto", "idUsuarioInterno", "fechaRegistro", "activo")
SELECT
    1,
        '<!DOCTYPE html><html lang="es"><head> <meta charset="UTF-8" /> <meta name="viewport" content="width=device-width, initial-scale=1.0" /> <title>Contraseña Temporal</title> <style> * { margin: 0; padding: 0; box-sizing: border-box; } body { background-color: #f0f4f8; font-family: "Segoe UI", Arial, sans-serif; -webkit-text-size-adjust: 100%; } .wrapper { width: 100%; padding: 40px 16px; background-color: #f0f4f8; } .card { max-width: 560px; margin: 0 auto; background-color: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08); } .header { background: linear-gradient(135deg, #003087 0%, #0057b8 100%); padding: 36px 40px; text-align: center; } .header-logo { font-size: 26px; font-weight: 700; color: #ffffff; letter-spacing: 2px; text-transform: uppercase; } .header-logo span { color: #7eb8f7; } .header-subtitle { margin-top: 6px; font-size: 12px; color: #a8c8f0; letter-spacing: 1px; text-transform: uppercase; } .body { padding: 40px 40px 32px; } .greeting { font-size: 20px; font-weight: 600; color: #1a2e4a; margin-bottom: 16px; } .text { font-size: 15px; color: #4a5568; line-height: 1.7; margin-bottom: 16px; } .password-box { margin: 28px 0; background-color: #f7faff; border: 2px dashed #0057b8; border-radius: 10px; padding: 24px; text-align: center; } .password-value { font-size: 28px; font-weight: 700; color: #003087; letter-spacing: 6px; font-family: "Courier New", monospace; text-align: center; } .warning-box { background-color: #fff8e6; border-left: 4px solid #f5a623; border-radius: 0 8px 8px 0; padding: 14px 18px; margin-bottom: 24px; } .warning-box p { font-size: 13px; color: #7a5800; line-height: 1.6; } .warning-box strong { color: #5a4000; } .steps-title { font-size: 13px; font-weight: 600; color: #1a2e4a; margin-bottom: 12px; text-transform: uppercase; letter-spacing: 0.5px; } .steps { list-style: decimal; list-style-position: inside; margin-bottom: 28px; padding-left: 4px; } .steps li { font-size: 14px; color: #4a5568; line-height: 1.5; margin-bottom: 10px; } .divider { border: none; border-top: 1px solid #e8edf3; margin: 0 0 24px; } .help-text { font-size: 13px; color: #718096; line-height: 1.6; } .help-text a { color: #0057b8; text-decoration: none; } .footer { background-color: #f7f9fc; border-top: 1px solid #e8edf3; padding: 24px 40px; text-align: center; } .footer p { font-size: 12px; color: #a0aec0; line-height: 1.7; } .footer strong { color: #718096; } @media (max-width: 480px) { .header { padding: 28px 24px; } .body { padding: 28px 24px 24px; } .footer { padding: 20px 24px; } .password-value { font-size: 22px; letter-spacing: 4px; } } </style></head><body> <div class="wrapper"> <div class="card"> <div class="header"> <div class="header-logo">JAP<span>DEVA</span></div> <div class="header-subtitle">Sistema de Gestión Institucional</div> </div> <div class="body"> <p class="greeting">Hola, {{NOMBRE}}</p> <p class="text">Recibimos una solicitud para restablecer la contraseña asociada a tu cuenta. A continuación, encontrarás tu <strong>contraseña temporal</strong>:</p> <div class="password-box"> <p class="password-value">{{CONTRASENA_TEMPORAL}}</p> </div> <div class="warning-box"> <p><strong>Importante:</strong> Esta contraseña es válida por <strong>24 horas</strong>. Por seguridad, te recomendamos cambiarla inmediatamente después de iniciar sesión.</p> </div> <p class="steps-title">¿Cómo continuar?</p> <ol class="steps"> <li>Ingresa a la aplicación con tu correo y la contraseña temporal.</li> <li>Dirígete a <strong>Mi Perfil → Cambiar contraseña</strong>.</li> <li>Establece una nueva contraseña segura.</li> </ol> <hr class="divider" /> <p class="help-text">Si no solicitaste este cambio, puedes ignorar este correo. Tu contraseña actual permanecerá sin cambios. Si tienes dudas, contacta al soporte técnico en <a href="mailto:{{CORREO_SOPORTE}}">{{CORREO_SOPORTE}}</a>.</p> </div> <div class="footer"> <p><strong>JAPDEVA</strong> · Junta de Administración Portuaria y de Desarrollo Económico de la Vertiente Atlántica<br />Este correo fue generado automáticamente, por favor no respondas a este mensaje.<br />&copy; {{ANIO}} JAPDEVA. Todos los derechos reservados.</p> </div> </div> </div></body></html>',
        TRUE,
        'Recuperación de contraseña',
        1,
        NOW(),
        TRUE
WHERE NOT EXISTS (SELECT 1 FROM "Tbl_PlantillaCorreo" WHERE "id" = 1);

INSERT INTO "Tbl_PlantillaCorreo" ("id", "Plantilla", "EsHtml", "Asunto", "idUsuarioInterno", "fechaRegistro", "activo")
SELECT
    2,
        '<!DOCTYPE html><html lang="es"><head> <meta charset="UTF-8" /> <meta name="viewport" content="width=device-width, initial-scale=1.0" /> <title>Reclamo en Revisión</title> <style> * { margin: 0; padding: 0; box-sizing: border-box; } body { background-color: #f0f4f8; font-family: "Segoe UI", Arial, sans-serif; -webkit-text-size-adjust: 100%; } .wrapper { width: 100%; padding: 40px 16px; background-color: #f0f4f8; } .card { max-width: 560px; margin: 0 auto; background-color: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08); } .header { background: linear-gradient(135deg, #003087 0%, #0057b8 100%); padding: 36px 40px; text-align: center; } .header-logo { font-size: 26px; font-weight: 700; color: #ffffff; letter-spacing: 2px; text-transform: uppercase; } .header-logo span { color: #7eb8f7; } .header-subtitle { margin-top: 6px; font-size: 12px; color: #a8c8f0; letter-spacing: 1px; text-transform: uppercase; } .body { padding: 40px 40px 32px; } .greeting { font-size: 20px; font-weight: 600; color: #1a2e4a; margin-bottom: 16px; } .text { font-size: 15px; color: #4a5568; line-height: 1.7; margin-bottom: 16px; } .reclamo-box { margin: 28px 0; background-color: #f7faff; border: 2px solid #0057b8; border-radius: 10px; padding: 24px; text-align: center; } .reclamo-label { font-size: 12px; color: #718096; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 8px; } .reclamo-id { font-size: 32px; font-weight: 700; color: #003087; letter-spacing: 4px; font-family: "Courier New", monospace; } .status-box { display: flex; align-items: center; background-color: #eaf4ff; border-left: 4px solid #0057b8; border-radius: 0 8px 8px 0; padding: 14px 18px; margin-bottom: 24px; } .status-box p { font-size: 13px; color: #1a3a6e; line-height: 1.6; } .status-box strong { color: #003087; } .steps-title { font-size: 13px; font-weight: 600; color: #1a2e4a; margin-bottom: 12px; text-transform: uppercase; letter-spacing: 0.5px; } .steps { list-style: decimal; list-style-position: inside; margin-bottom: 28px; padding-left: 4px; } .steps li { font-size: 14px; color: #4a5568; line-height: 1.5; margin-bottom: 10px; } .divider { border: none; border-top: 1px solid #e8edf3; margin: 0 0 24px; } .help-text { font-size: 13px; color: #718096; line-height: 1.6; } .help-text a { color: #0057b8; text-decoration: none; } .footer { background-color: #f7f9fc; border-top: 1px solid #e8edf3; padding: 24px 40px; text-align: center; } .footer p { font-size: 12px; color: #a0aec0; line-height: 1.7; } .footer strong { color: #718096; } @media (max-width: 480px) { .header { padding: 28px 24px; } .body { padding: 28px 24px 24px; } .footer { padding: 20px 24px; } .reclamo-id { font-size: 24px; letter-spacing: 2px; } } </style></head><body> <div class="wrapper"> <div class="card"> <div class="header"> <div class="header-logo">JAP<span>DEVA</span></div> <div class="header-subtitle">Sistema de Gestión Institucional</div> </div> <div class="body"> <p class="greeting">Hola, {{NOMBRE}}</p> <p class="text">Hemos recibido tu reclamo y queremos informarte que ha sido registrado exitosamente en nuestro sistema. Nuestro equipo comenzará a revisarlo a la brevedad.</p> <div class="reclamo-box"> <p class="reclamo-label">Número de reclamo</p> <p class="reclamo-id"># {{ID_RECLAMO}}</p> </div> <div class="status-box"> <p><strong>Estado actual:</strong> Tu reclamo se encuentra <strong>en proceso de revisión</strong>. Te notificaremos por este medio cuando haya una actualización.</p> </div> <p class="steps-title">¿Qué sucede ahora?</p> <ol class="steps"> <li>Nuestro equipo analiza los detalles de tu reclamo.</li> <li>Se asigna un responsable para gestionar tu caso.</li> <li>Recibirás una respuesta con la resolución correspondiente.</li> </ol> <hr class="divider" /> <p class="help-text">Si tienes consultas adicionales sobre tu reclamo, puedes comunicarte con nosotros indicando el número <strong># {{ID_RECLAMO}}</strong> al correo <a href="mailto:{{CORREO_SOPORTE}}">{{CORREO_SOPORTE}}</a>.</p> </div> <div class="footer"> <p><strong>JAPDEVA</strong> · Junta de Administración Portuaria y de Desarrollo Económico de la Vertiente Atlántica<br />Este correo fue generado automáticamente, por favor no respondas a este mensaje.<br />&copy; {{ANIO}} JAPDEVA. Todos los derechos reservados.</p> </div> </div> </div></body></html>',
        TRUE,
        'Registro de reclamo',
        1,
        NOW(),
        TRUE
WHERE NOT EXISTS (SELECT 1 FROM "Tbl_PlantillaCorreo" WHERE "id" = 2);

INSERT INTO "Tbl_PlantillaCorreo" ("id", "Plantilla", "EsHtml", "Asunto", "idUsuarioInterno", "fechaRegistro", "activo")
SELECT
    3,
        '<!DOCTYPE html><html lang="es"><head> <meta charset="UTF-8" /> <meta name="viewport" content="width=device-width, initial-scale=1.0" /> <title>Nuevo Reclamo Ingresado</title> <style> * { margin: 0; padding: 0; box-sizing: border-box; } body { background-color: #f0f4f8; font-family: "Segoe UI", Arial, sans-serif; -webkit-text-size-adjust: 100%; } .wrapper { width: 100%; padding: 40px 16px; background-color: #f0f4f8; } .card { max-width: 560px; margin: 0 auto; background-color: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08); } .header { background: linear-gradient(135deg, #003087 0%, #0057b8 100%); padding: 36px 40px; text-align: center; } .header-logo { font-size: 26px; font-weight: 700; color: #ffffff; letter-spacing: 2px; text-transform: uppercase; } .header-logo span { color: #7eb8f7; } .header-subtitle { margin-top: 6px; font-size: 12px; color: #a8c8f0; letter-spacing: 1px; text-transform: uppercase; } .badge { display: inline-block; margin-top: 14px; background-color: rgba(255,255,255,0.15); border: 1px solid rgba(255,255,255,0.3); border-radius: 20px; padding: 4px 16px; font-size: 11px; color: #e0eeff; letter-spacing: 1px; text-transform: uppercase; } .body { padding: 40px 40px 32px; } .intro { font-size: 15px; color: #4a5568; line-height: 1.7; margin-bottom: 24px; } .info-card { background-color: #f7faff; border: 1px solid #d0e4f7; border-radius: 10px; overflow: hidden; margin-bottom: 24px; } .info-card-header { background-color: #0057b8; padding: 10px 20px; } .info-card-header p { font-size: 11px; font-weight: 700; color: #ffffff; text-transform: uppercase; letter-spacing: 1px; } .info-row { display: flex; align-items: center; padding: 14px 20px; border-bottom: 1px solid #e2edf7; } .info-row:last-child { border-bottom: none; } .info-label { font-size: 12px; color: #718096; text-transform: uppercase; letter-spacing: 0.5px; width: 130px; flex-shrink: 0; } .info-value { font-size: 14px; color: #1a2e4a; font-weight: 600; } .info-value.highlight { font-size: 18px; color: #003087; font-family: "Courier New", monospace; letter-spacing: 3px; } .alert-box { background-color: #fff8e6; border-left: 4px solid #f5a623; border-radius: 0 8px 8px 0; padding: 14px 18px; margin-bottom: 24px; } .alert-box p { font-size: 13px; color: #7a5800; line-height: 1.6; } .alert-box strong { color: #5a4000; } .divider { border: none; border-top: 1px solid #e8edf3; margin: 0 0 24px; } .note { font-size: 13px; color: #718096; line-height: 1.6; } .footer { background-color: #f7f9fc; border-top: 1px solid #e8edf3; padding: 24px 40px; text-align: center; } .footer p { font-size: 12px; color: #a0aec0; line-height: 1.7; } .footer strong { color: #718096; } @media (max-width: 480px) { .header { padding: 28px 24px; } .body { padding: 28px 24px 24px; } .footer { padding: 20px 24px; } .info-label { width: 100px; } } </style></head><body> <div class="wrapper"> <div class="card"> <div class="header"> <div class="header-logo">JAP<span>DEVA</span></div> <div class="header-subtitle">Sistema de Gestión Institucional</div> <div class="badge">Notificación Interna</div> </div> <div class="body"> <p class="intro">Se ha registrado un nuevo reclamo en el sistema. A continuación se detallan los datos del caso para su atención y seguimiento.</p> <div class="info-card"> <div class="info-card-header"><p>Información del reclamo</p></div> <div class="info-row"> <span class="info-label">N.° de reclamo</span> <span class="info-value highlight"># {{ID_RECLAMO}}</span> </div> <div class="info-row"> <span class="info-label">Presentado por</span> <span class="info-value">{{NOMBRE}}</span> </div> <div class="info-row"> <span class="info-label">Estado</span> <span class="info-value">Pendiente de revisión</span> </div> </div> <div class="alert-box"> <p><strong>Acción requerida:</strong> Este reclamo debe ser asignado y atendido a la brevedad según los procedimientos internos establecidos por JAPDEVA.</p> </div> <hr class="divider" /> <p class="note">Este mensaje es una notificación automática del sistema. Para acceder al detalle completo del reclamo, ingrese al app.</p> </div> <div class="footer"> <p><strong>JAPDEVA</strong> · Junta de Administración Portuaria y de Desarrollo Económico de la Vertiente Atlántica<br />Este correo fue generado automáticamente, por favor no respondas a este mensaje.<br />&copy; {{ANIO}} JAPDEVA. Todos los derechos reservados.</p> </div> </div> </div></body></html>',
        TRUE,
        'Nuevo reclamo #{{ID_RECLAMO}}',
        1,
        NOW(),
        TRUE
WHERE NOT EXISTS (SELECT 1 FROM "Tbl_PlantillaCorreo" WHERE "id" = 3);

INSERT INTO "Tbl_PlantillaCorreo" ("id", "Plantilla", "EsHtml", "Asunto", "idUsuarioInterno", "fechaRegistro", "activo")
SELECT
    4,
        '<!DOCTYPE html><html lang="es"><head> <meta charset="UTF-8" /> <meta name="viewport" content="width=device-width, initial-scale=1.0" /> <title>Resolución de Reclamo</title> <style> * { margin: 0; padding: 0; box-sizing: border-box; } body { background-color: #f0f4f8; font-family: "Segoe UI", Arial, sans-serif; -webkit-text-size-adjust: 100%; } .wrapper { width: 100%; padding: 40px 16px; background-color: #f0f4f8; } .card { max-width: 560px; margin: 0 auto; background-color: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08); } .header { background: linear-gradient(135deg, #003087 0%, #0057b8 100%); padding: 36px 40px; text-align: center; } .header-logo { font-size: 26px; font-weight: 700; color: #ffffff; letter-spacing: 2px; text-transform: uppercase; } .header-logo span { color: #7eb8f7; } .header-subtitle { margin-top: 6px; font-size: 12px; color: #a8c8f0; letter-spacing: 1px; text-transform: uppercase; } .body { padding: 40px 40px 32px; } .greeting { font-size: 20px; font-weight: 600; color: #1a2e4a; margin-bottom: 16px; } .text { font-size: 15px; color: #4a5568; line-height: 1.7; margin-bottom: 24px; } .info-card { background-color: #f7faff; border: 1px solid #d0e4f7; border-radius: 10px; overflow: hidden; margin-bottom: 24px; } .info-card-header { background-color: #0057b8; padding: 10px 20px; } .info-card-header p { font-size: 11px; font-weight: 700; color: #ffffff; text-transform: uppercase; letter-spacing: 1px; } .info-row { display: flex; align-items: center; padding: 14px 20px; border-bottom: 1px solid #e2edf7; } .info-row:last-child { border-bottom: none; } .info-label { font-size: 12px; color: #718096; text-transform: uppercase; letter-spacing: 0.5px; width: 130px; flex-shrink: 0; } .info-value { font-size: 14px; color: #1a2e4a; font-weight: 600; } .info-value.reclamo-num { font-size: 18px; color: #003087; font-family: "Courier New", monospace; letter-spacing: 3px; } .estado-badge { display: inline-block; padding: 4px 14px; border-radius: 20px; font-size: 12px; font-weight: 700; letter-spacing: 0.5px; background-color: #e6f4ea; color: #1a6b35; border: 1px solid #a8d5b5; } .resolucion-box { background-color: #f7faff; border: 1px solid #d0e4f7; border-radius: 10px; padding: 20px 24px; margin-bottom: 24px; } .resolucion-label { font-size: 11px; font-weight: 700; color: #0057b8; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 10px; } .resolucion-texto { font-size: 14px; color: #2d3748; line-height: 1.8; } .divider { border: none; border-top: 1px solid #e8edf3; margin: 0 0 24px; } .help-text { font-size: 13px; color: #718096; line-height: 1.6; } .help-text a { color: #0057b8; text-decoration: none; } .footer { background-color: #f7f9fc; border-top: 1px solid #e8edf3; padding: 24px 40px; text-align: center; } .footer p { font-size: 12px; color: #a0aec0; line-height: 1.7; } .footer strong { color: #718096; } @media (max-width: 480px) { .header { padding: 28px 24px; } .body { padding: 28px 24px 24px; } .footer { padding: 20px 24px; } .info-label { width: 100px; } .info-value.reclamo-num { font-size: 15px; } } </style></head><body> <div class="wrapper"> <div class="card"> <div class="header"> <div class="header-logo">JAP<span>DEVA</span></div> <div class="header-subtitle">Sistema de Gestión Institucional</div> </div> <div class="body"> <p class="greeting">Hola, {{NOMBRE}}</p> <p class="text">Nos complace informarte que tu reclamo ha sido atendido por nuestro equipo. A continuación encontrarás el detalle de la resolución correspondiente.</p> <div class="info-card"> <div class="info-card-header"><p>Detalle del reclamo</p></div> <div class="info-row"> <span class="info-label">N.° de reclamo</span> <span class="info-value reclamo-num"># {{ID_RECLAMO}}</span> </div> <div class="info-row"> <span class="info-label">Estado final</span> <span class="info-value"><span class="estado-badge">{{ESTADO}}</span></span> </div> </div> <div class="resolucion-box"> <p class="resolucion-label">Resolución</p> <p class="resolucion-texto">{{DESCRIPCION_RESOLUCION}}</p> </div> <hr class="divider" /> <p class="help-text">Si tienes alguna consulta sobre esta resolución, puedes comunicarte con nosotros indicando el número <strong># {{ID_RECLAMO}}</strong> al correo <a href="mailto:{{CORREO_SOPORTE}}">{{CORREO_SOPORTE}}</a>.</p> </div> <div class="footer"> <p><strong>JAPDEVA</strong> · Junta de Administración Portuaria y de Desarrollo Económico de la Vertiente Atlántica<br />Este correo fue generado automáticamente, por favor no respondas a este mensaje.<br />&copy; {{ANIO}} JAPDEVA. Todos los derechos reservados.</p> </div> </div> </div></body></html>',
        TRUE,
        'Resolución de tu reclamo #{{ID_RECLAMO}}',
        1,
        NOW(),
        TRUE
WHERE NOT EXISTS (SELECT 1 FROM "Tbl_PlantillaCorreo" WHERE "id" = 4);
